import { Component, OnInit, Input, Output, EventEmitter } from '@angular/core';
import { AdventureTimeService } from '../../../Shared/services/adventure-time.service';

@Component({
  selector: 'app-table-row',
  templateUrl: './table-row.component.html',
  styleUrls: ['./table-row.component.css']
})
export class TableRowComponent implements OnInit {

  @Input() character: any;
  @Input()
  columns: string[] = [];
    @Input()
  value!: string;
    @Input() url: string="";
    @Output() url1 = new EventEmitter<string>();
    @Input() searchword1: string ="";
    @Output() searchword = new EventEmitter<{ url: string, type: string }>();

  constructor(private atService: AdventureTimeService) { }

  ngOnInit() {
  }

    toggle(str: string)
    {
        this.atService.Updateclicks(str);
       this.url = str;
        //this.url1.emit(str);
        this.searchword.emit({ url: str, type: 'image' });

    }

}
<article class="result-card">
  <ng-container *ngFor="let col of columns; last as isLast">
    <div *ngIf="!isLast" class="result-card__field">
      {{ character[col] }}
    </div>

    <figure *ngIf="isLast" class="result-card__media">
      <a (click)="toggle(character['age'])" class="media-link" target="iframe_a" [href]="character[col]">
        <img class="result-card__image" alt="Search result preview" [src]="character[col]" />
      </a>
      <figcaption class="result-card__actions">
        <a class="view-link" [href]="character[col]" target="_blank" rel="noopener">View</a>
        <label class="bookmark-toggle">
          <input type="checkbox" (click)="toggle(character[col])" />
          <span>Book Mark</span>
        </label>
      </figcaption>
    </figure>
  </ng-container>
</article>
